// External synthetic probe. Runs every minute from the Synthetics service —
// outside the VPC, over the public internet, through API Gateway — so it
// exercises the same path a real client takes rather than a shortcut into the
// private subnets.
//
// This is the only check that can distinguish "nobody is using TillFlow" from
// "TillFlow is down". Every alarm in alarms.tf treats missing data as
// not-breaching, which is correct for a system with idle periods and useless
// for detecting total failure. The probe supplies the constant traffic that
// makes silence meaningful.

// Only the logger, so the probe's own lines land in the canary's log group
// alongside the run artifacts. Global fetch is used rather than the Synthetics
// HTTP helpers — it needs Node 18+, which is why the runtime version in
// synthetics.tf is pinned to syn-nodejs-puppeteer-9.0 rather than left to
// default.
const log = require('SyntheticsLogger');

const BASE_URL = process.env.PROBE_BASE_URL;

// Deliberately unauthenticated endpoints only. The probe holds no service-auth
// secret: a credential that sits in a canary running every minute forever is a
// credential that will eventually leak, and /health plus /ready already answer
// the question the SLI asks — is the service up, and is its database reachable.
const CHECKS = [
  { name: 'payments-health', path: '/health', expect: 200, body: { status: 'ok' } },
  { name: 'payments-ready', path: '/ready', expect: 200, body: { status: 'ready' } },
];

async function probeEndpoint(check) {
  const url = `${BASE_URL}${check.path}`;
  const started = Date.now();

  const response = await fetch(url, {
    method: 'GET',
    headers: { 'User-Agent': 'tillflow-synthetic-probe' },
    signal: AbortSignal.timeout(10000),
  });
  const elapsed = Date.now() - started;
  const text = await response.text();

  log.info(`${check.name}: ${response.status} in ${elapsed}ms`);

  if (response.status !== check.expect) {
    throw new Error(`${check.name}: expected ${check.expect}, got ${response.status} — ${text.slice(0, 200)}`);
  }

  // A 200 with the wrong body is a real failure mode here: API Gateway answers
  // 200 with its own error payload when a VPC Link integration is misconfigured,
  // so status alone would report a broken gateway as healthy.
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch {
    throw new Error(`${check.name}: 200 but body was not JSON — ${text.slice(0, 200)}`);
  }
  for (const [key, value] of Object.entries(check.body)) {
    if (parsed[key] !== value) {
      throw new Error(`${check.name}: expected ${key}="${value}", got "${parsed[key]}"`);
    }
  }

  // No custom metric is emitted here on purpose: Synthetics already publishes
  // SuccessPercent, Duration and Failed per canary to CloudWatchSynthetics,
  // and those are what the alarm and the Grafana uptime panels read.
  return elapsed;
}

const handler = async function () {
  if (!BASE_URL) throw new Error('PROBE_BASE_URL is not set — the canary has no target');

  const failures = [];
  for (const check of CHECKS) {
    try {
      await probeEndpoint(check);
    } catch (error) {
      log.error(error.message);
      failures.push(error.message);
    }
  }

  // Every check runs even after one fails. A probe that stops at the first
  // error reports "payments is down" when the real story is "payments is up
  // but its database is not", and those have different first actions.
  if (failures.length) throw new Error(failures.join(' | '));

  return 'ok';
};

exports.handler = handler;
